command:
if (!game.user.isGM) {
  ui.notifications.warn("Apenas o mestre pode revelar handouts.");
  return;
}

const NOME_JOURNAL_MUNDO = "Handouts Revelados";
const PACKS_HANDOUTS = ["op2e-playtest.materiais-de-jogo"];

// 1) Junta todas as paginas de handout (tipo imagem) dos compendios de Materiais de Jogo.
let todasPaginas = [];
for (const packId of PACKS_HANDOUTS) {
  const pack = game.packs.get(packId);
  if (!pack) continue;
  const index = await pack.getIndex();
  const entradasHandouts = index.filter((e) => e.name.toLowerCase().includes("handout"));
  for (const entrada of entradasHandouts) {
    const journal = await pack.getDocument(entrada._id);
    for (const pagina of journal.pages) {
      if (pagina.type === "image") todasPaginas.push(pagina);
    }
  }
}

if (!todasPaginas.length) {
  ui.notifications.warn("Nenhum handout encontrado nos compêndios de Materiais de Jogo.");
  return;
}

// 2) Acha (ou cria) o Journal do mundo que fica visível aos jogadores, onde os handouts
//    revelados vao se acumulando -- diferente de "Mostrar Imagem", que so aparece na hora
//    e depois some, aqui fica salvo pra sempre no Journal deles.
let journalMundo = game.journal.getName(NOME_JOURNAL_MUNDO);
if (!journalMundo) {
  journalMundo = await JournalEntry.create({
    name: NOME_JOURNAL_MUNDO,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER }
  });
}

const jaRevelados = new Set(journalMundo.pages.map((p) => p.name));
const disponiveis = todasPaginas
  .filter((p) => !jaRevelados.has(p.name))
  .sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));

if (!disponiveis.length) {
  ui.notifications.info("Todos os handouts já foram revelados aos jogadores.");
  return;
}

const opcoes = disponiveis.map((p, i) => `<option value="${i}">${p.name}</option>`).join("");
const escolha = await foundry.applications.api.DialogV2.input({
  window: { title: "Revelar Handout" },
  content: `<div class="form-group"><label>Qual handout revelar pros jogadores?</label><select name="idx" style="width:100%">${opcoes}</select></div>`,
  ok: { label: "Revelar" }
});
if (!escolha) return;

const paginaOriginal = disponiveis[Number(escolha.idx)];
const dadosPagina = paginaOriginal.toObject();
delete dadosPagina._id;
dadosPagina.ownership = { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER };

const [paginaNova] = await journalMundo.createEmbeddedDocuments("JournalEntryPage", [dadosPagina]);

// 3) Mostra o pop-up pra todo mundo na hora, alem de deixar salvo permanentemente no Journal
//    "Handouts Revelados" (visivel a qualquer jogador a partir de agora).
new foundry.applications.apps.ImagePopout({
  src: paginaNova.src,
  window: { title: paginaNova.name },
  uuid: paginaNova.uuid
}).shareImage();

ui.notifications.info(`Handout "${paginaNova.name}" liberado! Já apareceu na tela dos jogadores e fica salvo no Journal "Handouts Revelados" pra sempre.`);
